176	  /**
177	   * Give the unit a worktree branched from the integration tip. A recorded worktree is reused so a retry or a resume
178	   * continues on the same files; an operator restart throws the old worktree and branch away first.
179	   */
180	  prepareUnit(unit: WorkUnit, options: { restart?: boolean } = {}): UnitGitPreparation {
181	    const recorded = this.state.units[unit.id];
182	    const branch = recorded?.branch ?? `nexus/op-${this.plan.key}/${gitSlug(unit.id)}`;
183	    const worktree = recorded?.worktree ?? path.join(this.plan.baseDir, "units", gitSlug(unit.id));
184	
185	    const restart = Boolean(options.restart && recorded);
186	    let restartBranch = branch;
187	    if (restart) {
188	      // The worktree may be gone while its registration survives; prune before deleting the branch, or `branch -D`
189	      // refuses and the restart silently resumes the old work.
190	      this.removeWorktree(recorded!.worktree);
191	      gitResult(this.plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
192	      gitResult(this.plan.repoRoot, ["branch", "-D", recorded!.branch]);
193	    }
194	
195	    if (fs.existsSync(worktree) && !restart) {
196	      const existing = this.state.units[unit.id];
197	      if (!existing) {
198	        throw new Error(`worktree ${worktree} exists but is not recorded for unit ${unit.id}; remove it or restart the unit`);
199	      }
200	      return { workspace: worktree, branch: existing.branch, reused: true };
201	    }
202	    if (fs.existsSync(worktree) && restart) gitResult(this.plan.repoRoot, ["worktree", "remove", "--force", worktree]);
203	
204	    let branchExists = gitResult(this.plan.repoRoot, ["rev-parse", "--verify", `refs/heads/${branch}`]).ok;
205	    if (restart && branchExists) {
206	      // Still checked out elsewhere: a restart must start from the tip, so use a fresh branch rather than resume it.
207	      restartBranch = `${branch}-${gitSlug(`${unit.id}-${Date.now()}`)}`;
208	      branchExists = false;
209	    }
210	    const add = () => branchExists
211	      ? gitResult(this.plan.repoRoot, ["worktree", "add", worktree, restartBranch])
212	      : gitResult(this.plan.repoRoot, ["worktree", "add", "-b", restartBranch, worktree, this.currentTip()]);
213	    // A worktree directory that disappeared outside Nexus leaves a registration behind; prune it, then add.
214	    gitResult(this.plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
215	    let added = add();
216	    if (!added.ok && /already registered|missing but already registered/i.test(added.stderr)) {
217	      gitResult(this.plan.repoRoot, ["worktree", "remove", "--force", worktree]);
218	      gitResult(this.plan.repoRoot, ["worktree", "prune", "--expire", "now"]);
