235	  async integrate(unit: WorkUnit, result: Extract<UnitRunResult, { kind: "completed" }>): Promise<IntegrateResult> {
236	    const entry = this.state.units[unit.id];
237	    if (!entry) return { kind: "failed", reason: `unit ${unit.id} has no worktree recorded` };
238	    if (entry.integratedCommit) {
239	      return {
240	        kind: "nothing",
241	        receipt: {
242	          unitId: unit.id,
243	          branch: entry.branch,
244	          commit: entry.integratedCommit,
245	          integratedCommit: entry.integratedCommit,
246	          mergedAt: new Date().toISOString(),
247	          files: [],
248	          outcome: result.outcome,
249	          summary: result.summary,
250	          verification: "ALREADY_INTEGRATED",
251	        },
252	      };
253	    }
254	    const worktreeMissing = !fs.existsSync(entry.worktree);
255	    const recoveredCommit = worktreeMissing ? this.mergedUnitCommit(entry) : undefined;
256	    if (worktreeMissing && !recoveredCommit) {
257	      return { kind: "failed", reason: `unit ${unit.id}'s worktree is missing (${entry.worktree})` };
258	    }
259	
260	    if (!worktreeMissing) {
261	      const branch = gitResult(entry.worktree, ["rev-parse", "--abbrev-ref", "HEAD"]);
262	      if (!branch.ok || branch.stdout.trim() !== entry.branch) {
263	        return { kind: "failed", reason: `unit ${unit.id}'s worktree is not on its recorded branch ${entry.branch}` };
264	      }
265	
266	      // Uncommitted agent work is the normal case; commit it without touching ignored build output.
267	      const dirty = gitResult(entry.worktree, ["status", "--porcelain"]).stdout.trim();
268	      if (dirty) {
269	        const added = gitResult(entry.worktree, ["add", "-A"]);
270	        if (!added.ok) return { kind: "failed", reason: `cannot stage ${unit.id}: ${added.stderr.trim()}` };
271	        const committed = gitResult(entry.worktree, [
272	          ...this.mechanicalGitConfig(), "commit", "--no-verify", "-q", "-m", `nexus: ${unit.title}`,
273	        ]);
274	        if (!committed.ok) {
275	          return { kind: "failed", reason: `cannot commit ${unit.id}: ${committed.stderr.trim() || "git commit failed"}` };
276	        }
277	      }
278	    }
279	    const commit = recoveredCommit ?? git(entry.worktree, ["rev-parse", "HEAD"]);
280	    if (commit === entry.baseCommit) {
281	      const tip = this.currentTip();
282	      this.state.units[unit.id] = { ...entry, integratedCommit: tip };
283	      return {
284	        kind: "nothing",
285	        receipt: {
286	          unitId: unit.id,
287	          branch: entry.branch,
288	          commit,
289	          integratedCommit: tip,
290	          mergedAt: new Date().toISOString(),
291	          files: [],
292	          outcome: result.outcome,
293	          summary: result.summary,
294	          verification: "NO_CHANGES",
295	        },
296	      };
297	    }
298	
299	    const tip = this.currentTip();
300	    // A branch already contained in the integration tip (crash after the merge) is recorded, not merged twice.
301	    if (gitResult(this.plan.integrationWorktree, ["merge-base", "--is-ancestor", commit, "HEAD"]).ok) {
302	      // The merge happened before a crash. The merged tree can no longer be reset safely, so the verifier is a
303	      // post-hoc check: a failure is reported for the operator, not silently recorded as verified.
304	      const posthoc = result.verification?.command && result.verification.status === "PASSED" && result.verification.hasExecutedTests
305	        ? this.verifyMerged(result.verification.command)
