 56	/** Reads stdin up to the first newline (or its end); anything after the newline is put back for the agent. */
 57	function readPayloadLine() {
 58	  return new Promise((resolve, reject) => {
 59	    let body = "";
 60	    const decoder = new StringDecoder("utf8");
 61	    const onData = (chunk) => {
 62	      body += decoder.write(chunk);
 63	      if (body.length > 1_000_000) { cleanup(); reject(new Error("sandbox launch payload too large")); return; }
