 65	      if (newline < 0) return;
 66	      cleanup();
 67	      process.stdin.pause();
 68	      const rest = body.slice(newline + 1);
 69	      if (rest) process.stdin.unshift(Buffer.from(rest, "utf8"));
 70	      resolve(body.slice(0, newline));
 71	    };
 72	    const onEnd = () => { cleanup(); resolve(body); };
 73	    const cleanup = () => { process.stdin.off("data", onData); process.stdin.off("end", onEnd); process.stdin.off("error", reject); };
