  9	const RUNTIMES = Object.freeze({ node: process.execPath, python3: "/usr/bin/python3" });
 10	const MAX_ORACLE_BYTES = 1_048_576;
 11	const MAX_CASES = 256;
 12	const MAX_CASE_BYTES = 16_384;
 13	const MAX_OUTPUT_BYTES = 32_768;
 14	const MAX_TIMEOUT_MS = 30_000;
 15	const MAX_TOTAL_TIMEOUT_MS = 300_000;
