 17	/** Validate a frozen black-box oracle definition without exposing its case contents in diagnostics. */
 18	export function blackBoxOracleProblem(check, taskDir, candidateFixture = null) {
 19	  if (!check || check.protocol !== "blackbox-v1") return "hidden oracle protocol must be blackbox-v1";
 20	  if (Object.keys(check).some((key) => !["protocol", "casesFile", "runtime", "argv", "timeoutMs", "totalTimeoutMs", "maxOutputBytes"].includes(key))) {
 21	    return "hidden black-box oracle has unsupported fields";
 22	  }
 23	  if (typeof check.casesFile !== "string") return "hidden black-box oracle casesFile is required";
 24	  let casesPath;
 25	  try { casesPath = confinedPath(taskDir, check.casesFile); }
 26	  catch { return "hidden black-box oracle casesFile is unsafe"; }
 27	  if (candidateFixture) {
 28	    let fixturePath;
 29	    try { fixturePath = confinedPath(taskDir, candidateFixture); }
 30	    catch { return "candidate fixture path is unsafe"; }
 31	    const relative = path.relative(fixturePath, casesPath);
 32	    if (relative === "" || (!relative.startsWith(`..${path.sep}`) && relative !== ".." && !path.isAbsolute(relative))) {
 33	      return "hidden black-box oracle casesFile must be outside the candidate fixture";
 34	    }
 35	  }
 36	  try {
 37	    const stat = fs.statSync(casesPath);
 38	    if (!stat.isFile() || stat.size > MAX_ORACLE_BYTES) return "hidden black-box oracle case file is not a bounded regular file";
 39	    const rows = JSON.parse(fs.readFileSync(casesPath, "utf8"));
 40	    if (!Array.isArray(rows) || rows.length < 1 || rows.length > MAX_CASES) return "hidden black-box oracle case count is outside the allowed range";
 41	    for (const row of rows) {
 42	      if (!row || typeof row !== "object" || Array.isArray(row) || Object.keys(row).sort().join(",") !== "expected,input") {
 43	        return "hidden black-box oracle cases must contain only input and expected fields";
 44	      }
 45	      if (Buffer.byteLength(JSON.stringify(row), "utf8") > MAX_CASE_BYTES) return "hidden black-box oracle case exceeds the size limit";
 46	    }
 47	  } catch {
 48	    return "hidden black-box oracle cases are unavailable or malformed";
 49	  }
 50	  if (!Object.hasOwn(RUNTIMES, check.runtime)) return "hidden black-box oracle runtime is not allowlisted";
 51	  if (check.runtime === "python3") {
 52	    const toolchainProblem = oracleToolchainsProblem();
 53	    if (toolchainProblem) return toolchainProblem;
 54	  }
 55	  if (!Array.isArray(check.argv) || check.argv.length !== 1 || typeof check.argv[0] !== "string" || check.argv[0].includes("\0") || Buffer.byteLength(check.argv[0]) > 1024) {
 56	    return "hidden black-box oracle argv must name only one candidate entrypoint";
 57	  }
 58	  const entrypoint = check.argv[0];
 59	  if (path.posix.isAbsolute(entrypoint) || entrypoint.startsWith("-") || entrypoint.includes("\\") || entrypoint.split("/").some((part) => !part || part === "." || part === "..")) {
 60	    return "hidden black-box oracle argv must be a normalized relative candidate entrypoint";
 61	  }
 62	  if (!Number.isSafeInteger(check.timeoutMs) || check.timeoutMs < 100 || check.timeoutMs > MAX_TIMEOUT_MS) return "hidden black-box oracle timeout is outside the allowed range";
 63	  if (!Number.isSafeInteger(check.totalTimeoutMs) || check.totalTimeoutMs < check.timeoutMs || check.totalTimeoutMs > MAX_TOTAL_TIMEOUT_MS) return "hidden black-box oracle total timeout is outside the allowed range";
 64	  if (!Number.isSafeInteger(check.maxOutputBytes) || check.maxOutputBytes < 2 || check.maxOutputBytes > MAX_OUTPUT_BYTES) return "hidden black-box oracle output limit is outside the allowed range";
 65	  return null;
 66	}
