 68	/** Run candidate code as a black box. Only bounded summaries leave this function; raw output is discarded. */
 69	export async function runBlackBoxOracle(task, workspace, check, { resources = null, protectedCorpusPaths = [] } = {}) {
 70	  const problem = blackBoxOracleProblem(check, task.dir, task.fixture ?? null);
 71	  if (problem) throw new Error(problem);
