 73	  const entrypoint = confinedPath(workspace, check.argv[0]);
 74	  if (!fs.statSync(entrypoint).isFile()) throw new Error("black-box candidate entrypoint is not a regular file");
 75	  const cases = JSON.parse(fs.readFileSync(casesPath, "utf8"));
 76	  const command = RUNTIMES[check.runtime];
 77	  const failures = [];
 78	  const timeoutCases = [];
 79	  const outputLimitCases = [];
 80	  const executionFailureCases = [];
 81	  const invalidOutputCases = [];
 82	  const mismatchCases = [];
 83	  const fixturePath = task.fixture ? confinedPath(task.dir, task.fixture) : null;
 84	  const candidateWorkspace = fs.realpathSync(workspace);
 85	  const relativeCases = path.relative(candidateWorkspace, casesPath);
 86	  if (relativeCases === "" || (!relativeCases.startsWith(`..${path.sep}`) && relativeCases !== ".." && !path.isAbsolute(relativeCases))) {
 87	    throw new Error("black-box oracle cases unexpectedly overlap the candidate workspace");
 88	  }
 89	  if (fixturePath) {
 90	    const relativeFixtureCases = path.relative(fixturePath, casesPath);
 91	    if (relativeFixtureCases === "" || (!relativeFixtureCases.startsWith(`..${path.sep}`) && relativeFixtureCases !== ".." && !path.isAbsolute(relativeFixtureCases))) {
 92	      throw new Error("black-box oracle cases unexpectedly overlap the copied candidate fixture");
 93	    }
 94	  }
 95	  const deadline = Date.now() + check.totalTimeoutMs;
 96	  const containment = { executions: 0, oomKills: 0, pidsMaxEvents: 0, survivorsAfterExit: 0 };
 97	  for (let index = 0; index < cases.length; index++) {
 98	    const remainingMs = deadline - Date.now();
 99	    if (remainingMs < 100) {
100	      const unrun = Array.from({ length: cases.length - index }, (_, offset) => index + offset);
101	      failures.push(...unrun);
102	      timeoutCases.push(...unrun);
103	      break;
104	    }
105	    const spec = isolatedProcessArgv({
106	      cwd: workspace,
107	      command,
108	      argv: [`/workspace/${check.argv[0]}`],
109	      readOnlyPaths: [command],
110	      allowedFiles: [command],
111	      workspaceReadOnly: true,
112	      timeoutMs: Math.min(check.timeoutMs, remainingMs),
113	      protectedCorpusPaths,
114	      oracleToolchains: check.runtime === "python3",
115	    });
116	    const result = await runIsolatedProcess(spec, {
117	      outputLimit: check.maxOutputBytes,
118	      input: `${JSON.stringify(cases[index].input)}\n`,
119	      resources,
120	    });
