122	    if (result.resources) {
123	      containment.executions++;
124	      containment.oomKills += result.resources.oomKills ?? 0;
125	      containment.pidsMaxEvents += result.resources.pidsMaxEvents ?? 0;
126	      containment.survivorsAfterExit += result.resources.survivorsAfterExit;
127	    }
128	    if (result.timedOut) timeoutCases.push(index);
129	    if (result.overflow) outputLimitCases.push(index);
130	    if (result.status !== 0 || result.error) executionFailureCases.push(index);
131	    let actual;
132	    let validOutput = false;
133	    if (result.status === 0 && !result.timedOut && !result.overflow && !result.error) {
134	      try {
135	        actual = JSON.parse(result.stdout);
136	        validOutput = true;
137	      } catch { /* Candidate output is intentionally never copied to diagnostics. */ }
138	    }
139	    if (!validOutput) invalidOutputCases.push(index);
140	    if (validOutput && !isDeepStrictEqual(actual, cases[index].expected)) mismatchCases.push(index);
141	    if (result.timedOut || result.overflow || result.status !== 0 || result.error || !validOutput || !isDeepStrictEqual(actual, cases[index].expected)) failures.push(index);
142	  }
143	  return {
144	    pass: failures.length === 0,
145	    cases: cases.length,
 60	    const result = spawnSync(command, argv, { encoding: "utf8", timeout: 5000 });
 61	    return result.status === 0 ? availableDirectory(result.stdout.trim()) : null;
 62	  };
 63	  hostToolchains = {
 64	    goRoot: selectToolchainRoot(fromCommand("go", ["env", "GOROOT"]), availableDirectory("/usr/local/go")),
 65	    rustRoot: availableDirectory("/opt/nexus-qual/rust") ?? fromCommand("rustc", ["--print", "sysroot"]),
