 70	/** Python black-box oracles may invoke only these root-owned, pinned compiler runtimes. */
 71	export function oracleToolchainsProblem() {
 72	  if (oracleToolchainPreflight !== undefined) return oracleToolchainPreflight;
 73	  for (const { root, required } of PINNED_ORACLE_TOOLCHAINS) {
 74	    let stat;
