 95	        }
 96	      }
 97	    } catch {
 98	      return (oracleToolchainPreflight = "pinned oracle toolchains are unavailable; refusing Python black-box qualification");
 99	    }
100	  }
101	  return (oracleToolchainPreflight = null);
102	}
