  3	//   node scripts/terminal-acceptance/summarize.mjs <evidence dir> --rc vX.Y.Z-rc.N --manifest-sha256 <hex> \
  4	//     [--dispositions dispositions.json]
  5	// --manifest-sha256 is the SHA-256 of MANIFEST.sha256 inside the RC release archive, so every cell must have run the
  6	// published RC package. The gate fails closed:
  7	//   - every terminal × size cell needs a complete, verified attempt (otherwise NOT RUN: ACCEPTANCE §1 rule 5);
  8	//   - an attempt is complete only when its self-hash, required evidence file hashes, both launch measurements and
  9	//     the mock log's scenario proof (approve x2 tool rounds, stream, sleep tool call) all verify; screenshots are
 10	//     optional under DEC-18 and, when supplied, both screenshot files must verify;
 11	//   - checks 2, 5 and 6 have zero FAIL in ANY attempt; a measured survivor or unrestored terminal turns PASS into FAIL;
 12	//   - every other FAIL, in any attempt, needs a written disposition keyed "<cell>:<check>";
 13	//   - an aborted attempt (a .partial file) needs a written disposition keyed "<cell>:partial-<n>".
 14	// Hashes prove the files are unchanged since recording, not who recorded them: commit the evidence directory.
 15	import { createHash } from "node:crypto";
 16	import fs from "node:fs";
 17	import path from "node:path";
 18	
 19	const TERMINALS = ["xterm", "kitty", "tmux-gnome", "vscode", "gnome"];
 20	const SIZES = ["80x24", "40x14", "200x60"];
 21	const CHECKS = ["1", "2", "3", "4", "5", "6", "7"];
 22	const SAFETY = new Set(["2", "5", "6"]);
 23	const REQUIRED_FILES = ["mockLog", "answers", "exits"];
 24	const OPTIONAL_SCREENSHOTS = ["approvalScreenshot", "postExitScreenshot"];
 25	const arg = (name) => (process.argv.includes(name) ? process.argv[process.argv.indexOf(name) + 1] : null);
 26	const dir = process.argv[2];
 27	const rc = arg("--rc");
 28	const manifestSha = arg("--manifest-sha256");
 29	if (!dir || !/^v\d+\.\d+\.\d+-rc\.\d+$/.test(rc ?? "") || !/^[0-9a-f]{64}$/.test(manifestSha ?? "")) {
 30	  console.error("usage: summarize.mjs <evidence dir> --rc vX.Y.Z-rc.N --manifest-sha256 <hex> [--dispositions file]");
