      const next = await jobs.next();
      if (failed || next.done) return;
      await scanRoots(next.value);
    } catch {
      failed = true;
      stopAll();
      return;
    }
  }
}

await Promise.all(Array.from({ length: SCAN_WORKERS }, () => worker()));
