"for f in ubuntu-22-04-node22-power-loss-durability-rc11-write.log ubuntu-22-04-node22-power-loss-durability-rc11-verify.log; do gh api \"repos/mikeholownych/nexus-code/contents/docs/reviews/evidence/v1-qualification/rc.10/platform-e2/$f?ref=bb335de6d943e54ff97f3fa03442dc267a91aa9b\" --jq .path >/dev/null 2>&1 && echo \"PRESENT $f\" || echo \"MISSING $f\"; done",
