];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/mike/nexus-code",yield_time_ms:10000,max_output_tokens:1000})));
for(let i=0;i<rs.length;i++)text("===== "+i+" =====\n"+rs[i].output+"exit="+rs[i].exit_code);

const files=[
".github/workflows/release.yml",
".github/workflows/ci.yml",
"cli/test/release_workflow_parity.test.ts"
];
for(const f of files){
const r=await tools.exec_command({cmd:`git diff --cached --binary 1acff70018c00c2459c388f34dfb2997b8b4d7c6 -- '${f}' | sha256sum`,workdir:"/home/mike/nexus-wt/pr335-release-parity-combination",yield_time_ms:10000,max_output_tokens:200});
text(f+" "+r.output);
}

