  1	/**
  2	 * The evaluation harness end to end against a scripted model (Stage 8, T1 smoke): fresh workspaces, hidden tests the
  3	 * agent never sees, separate scores. The self-test task is the assessment's A1 case: a repository whose own suite is
  4	 * green but never exercises the deliverable. A wrong deliverable must fail the hidden test and must never be VERIFIED.
  5	 */
  6	
  7	import { test } from "node:test";
  8	import assert from "node:assert/strict";
  9	import { createHash } from "node:crypto";
 10	import fs from "node:fs";
 11	import os from "node:os";
 12	import path from "node:path";
 13	import { spawn, spawnSync } from "node:child_process";
 14	import { fileURLToPath } from "node:url";
 15	import { startGateway, Reply } from "./helpers/fixtures.js";
 16	
 17	const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
 18	
 19	async function sealTestTasks(tasksDir: string, taskId: string) {
 20	  const { corpusTaskRows } = await import(path.join(ROOT, "eval/validate.mjs"));
 21	  const rows = corpusTaskRows(tasksDir, [taskId]);
 22	  const manifestPath = path.join(tasksDir, "custody-manifest.json");
 23	  const manifest = { schemaVersion: 1, split: "heldout", custody: { status: "approved", custodian: "synthetic-test-role", approvedAt: "2026-01-01T00:00:00Z" }, tasks: rows };
 24	  const bytes = JSON.stringify(manifest);
 25	  fs.writeFileSync(manifestPath, bytes);
 26	  return { corpusManifest: manifestPath, corpusManifestSha256: createHash("sha256").update(bytes).digest("hex") };
 27	}
 28	
 29	/** Async: the scripted gateway answers from this process, so the runner must not block its event loop. */
 30	function runNode(argv: string[], env: NodeJS.ProcessEnv = process.env): Promise<{ status: number | null; stdout: string; stderr: string }> {
 31	  return new Promise((resolve) => {
 32	    const child = spawn(process.execPath, argv, { stdio: ["ignore", "pipe", "pipe"], env });
 33	    let stdout = "";
 34	    let stderr = "";
 35	    child.stdout.on("data", (c) => (stdout += c));
 36	    child.stderr.on("data", (c) => (stderr += c));
 37	    child.on("close", (status) => resolve({ status, stdout, stderr }));
 38	  });
 39	}
 40	
 41	function writer(content: string) {
 42	  return (_n: number, body: any): Reply => {
 43	    const tools = (body?.messages ?? []).filter((m: any) => m.role === "tool").length;
 44	    if (tools === 0) return { kind: "tools", calls: [{ name: "write_file", args: { path: "math.js", content } }] };
 45	    if (tools === 1) return { kind: "tools", calls: [{ name: "task_completed", args: { summary: "math.js added" } }] };
 46	    return { kind: "text", content: "Done." };
 47	  };
 48	}
 49	
 50	async function evaluate(content: string, extra: Record<string, unknown> = {}): Promise<{ records: any[]; score: any; hiddenLog: string; agentLog: string; agentError: string }> {
 51	  const gw = await startGateway(writer(content));
 52	  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-out-"));
 53	  const out = path.join(root, "run");
 54	  const config = path.join(root, "config.json");
 55	  fs.writeFileSync(config, JSON.stringify({ name: "nexus@mock", agent: "nexus", endpoint: gw.url, model: "m", runs: 1, steps: 20, minutes: 5, ...extra }));
 56	  try {
 57	    const run = await runNode([path.join(ROOT, "eval/run.mjs"), "--config", config, "--out", out, "--only", "selftest-add"]);
 58	    assert.equal(run.status, 0, `${run.stdout}\n${run.stderr}`);
 59	    const records = fs.readFileSync(path.join(out, "results.jsonl"), "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
 60	    const scored = spawnSync(process.execPath, [path.join(ROOT, "eval/score.mjs"), path.join(out, "results.jsonl"), "--json"], { encoding: "utf8" });
 61	    assert.equal(scored.status, 0, scored.stderr);
 62	    const manifest = JSON.parse(fs.readFileSync(path.join(out, "manifest.json"), "utf8"));
 63	    assert.deepEqual(manifest.tasks.map((task: any) => task.id), ["selftest-add"]);
 64	    assert.match(manifest.harness.sourceSha256, /^[0-9a-f]{64}$/);
 65	    assert.match(manifest.configSha256, /^[0-9a-f]{64}$/);
 66	    const priorResults = fs.readFileSync(path.join(out, "results.jsonl"), "utf8");
 67	    const replay = await runNode([path.join(ROOT, "eval/run.mjs"), "--config", config, "--out", out, "--only", "selftest-add"]);
 68	    assert.equal(replay.status, 2);
 69	    assert.match(replay.stderr, /output directory must be new/);
 70	    assert.equal(fs.readFileSync(path.join(out, "results.jsonl"), "utf8"), priorResults, "reusing an output directory changed prior evidence");
 71	    assert.match(manifest.harness.string, /^[0-9a-f]{12}/);
 72	    const logDir = records[0].logs ? path.join(out, records[0].logs) : null;
 73	    const readLog = (file: string) => logDir && fs.existsSync(path.join(logDir, file)) ? fs.readFileSync(path.join(logDir, file), "utf8") : "<not written>";
 74	    return { records, score: JSON.parse(scored.stdout), hiddenLog: readLog("hidden.log"), agentLog: readLog("agent.stdout.json"), agentError: readLog("agent.stderr.log") };
 75	  } finally {
 76	    await gw.close();
 77	    fs.rmSync(root, { recursive: true, force: true });
 78	  }
 79	}
