 12	import path from "node:path";
 13	import { spawn, spawnSync } from "node:child_process";
 14	import { fileURLToPath } from "node:url";
 15	import { startGateway, Reply } from "./helpers/fixtures.js";
 16	
 17	const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
 18	
 19	async function sealTestTasks(tasksDir: string, taskId: string) {
 20	  const { corpusTaskRows } = await import(path.join(ROOT, "eval/validate.mjs"));
 21	  const rows = corpusTaskRows(tasksDir, [taskId]);
 22	  const manifestPath = path.join(tasksDir, "custody-manifest.json");
 23	  const manifest = { schemaVersion: 1, split: "heldout", custody: { status: "approved", custodian: "synthetic-test-role", approvedAt: "2026-01-01T00:00:00Z" }, tasks: rows };
 24	  const bytes = JSON.stringify(manifest);
 25	  fs.writeFileSync(manifestPath, bytes);
 26	  return { corpusManifest: manifestPath, corpusManifestSha256: createHash("sha256").update(bytes).digest("hex") };
 27	}
 28	
 29	/** Async: the scripted gateway answers from this process, so the runner must not block its event loop. */
 30	function runNode(argv: string[], env: NodeJS.ProcessEnv = process.env): Promise<{ status: number | null; stdout: string; stderr: string }> {
 31	  return new Promise((resolve) => {
 32	    const child = spawn(process.execPath, argv, { stdio: ["ignore", "pipe", "pipe"], env });
 33	    let stdout = "";
 34	    let stderr = "";
 35	    child.stdout.on("data", (c) => (stdout += c));
 36	    child.stderr.on("data", (c) => (stderr += c));
 37	    child.on("close", (status) => resolve({ status, stdout, stderr }));
 38	  });
 39	}
 40	
 41	function writer(content: string) {
 42	  return (_n: number, body: any): Reply => {
 43	    const tools = (body?.messages ?? []).filter((m: any) => m.role === "tool").length;
 44	    if (tools === 0) return { kind: "tools", calls: [{ name: "write_file", args: { path: "math.js", content } }] };
 45	    if (tools === 1) return { kind: "tools", calls: [{ name: "task_completed", args: { summary: "math.js added" } }] };
 46	    return { kind: "text", content: "Done." };
 47	  };
 48	}
