 50	async function evaluate(content: string, extra: Record<string, unknown> = {}): Promise<{ records: any[]; score: any; hiddenLog: string; agentLog: string; agentError: string }> {
 51	  const gw = await startGateway(writer(content));
 52	  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-out-"));
 53	  const out = path.join(root, "run");
